    val capturedAt = remember(selectedId, activeResult) { Date() }
    val capturedUserName =
        remember(selectedId, activeResult) {
            repo.getUserProfile().displayName
        }

    val finalText =
        remember(
            selectedId,
            activeResult,
            templates,
            capturedAt,
            capturedUserName
        ) {
            applyReportTemplate(
                template = selected,
                result = activeResult,
                userName = capturedUserName,
                now = capturedAt
            )
