class DataManagementActivity : ComponentActivity() {
    private var backupBusy by mutableStateOf(false)
    private var pendingBackupBytes: ByteArray? = null
    private var selectedRestoreBytes: ByteArray? = null

    private val createBackupFile =
        registerForActivityResult(
            ActivityResultContracts.CreateDocument(
                "application/octet-stream"
            )
        ) { uri ->
            val bytes = pendingBackupBytes
            pendingBackupBytes = null

            if (uri != null && bytes != null) {
                runCatching {
                    contentResolver.openOutputStream(uri)?.use {
                        it.write(bytes)
                    } ?: error("openOutputStream failed")
                }.onSuccess {
                    Toast.makeText(
                        this,
                        "백업 파일을 저장했습니다.",
                        Toast.LENGTH_SHORT
                    ).show()
                }.onFailure {
                    Toast.makeText(
                        this,
                        "백업 파일을 저장할 수 없습니다.",
                        Toast.LENGTH_SHORT
                    ).show()
                }
            }
        }

    private val openRestoreFile =
        registerForActivityResult(
            ActivityResultContracts.OpenDocument()
        ) { uri ->
            if (uri != null) {
                selectedRestoreBytes =
                    readUriBytesSafely(uri)

                selectedRestoreBytes?.let {
                    onRestoreFileSelected?.invoke(it)
                }
            }
        }

    private var onRestoreFileSelected:
        ((ByteArray) -> Unit)? = null

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        ArmyristPortableDataManager
            .recoverInterruptedRestore(this)

        setContent {
            ArmyristTheme {
                Surface(
                    Modifier.fillMaxSize(),
                    color = ArmyristColors.AppBackground
                ) {
                    DataManagementScreen(
                        onBack = { finish() },
                        backupBusy = backupBusy,
                        onCreateBackup = { encrypted, password ->
                            if (!backupBusy) {
                                backupBusy = true
                                lifecycleScope.launch {
                                    try {
                                        val chars = if (encrypted) password.toCharArray() else null
                                        val result = withContext(Dispatchers.Default) {
                                            try {
                                                ArmyristPortableDataManager.createFullBackup(this@DataManagementActivity, chars)
                                            } finally { chars?.fill('\u0000') }
                                        }
                                        when (result) {
                                            is PortableResult.Success -> {
                                                pendingBackupBytes = result.value
                                                createBackupFile.launch("armyrist-backup-${LocalDate.now()}.armyrist")
                                            }
                                            is PortableResult.Error -> Toast.makeText(
                                                this@DataManagementActivity, result.message, Toast.LENGTH_LONG
                                            ).show()
                                        }
                                    } finally { backupBusy = false }
                                }
                            }
                        },
                        onChooseRestoreFile = { callback ->
                            onRestoreFileSelected = callback
                            openRestoreFile.launch(
                                arrayOf(
                                    "application/octet-stream",
                                    "application/json",
                                    "*/*"
                                )
                            )
                        },
                        onRestoreValidated = { backup ->
                            when (
                                ArmyristPortableDataManager
                                    .restoreFullBackup(
                                        this,
                                        backup
                                    )
                            ) {
                                is PortableResult.Success -> {
                                    (application as ArmyristApplication)
                                        .reloadAfterPortableDataChange()
                                    Toast.makeText(
                                        this,
                                        "전체 복원이 완료되었습니다.",
                                        Toast.LENGTH_SHORT
                                    ).show()
                                    true
                                }
                                is PortableResult.Error -> false
                            }
                        }
                    )
                }
            }
        }
    }

    private fun readUriBytesSafely(uri: Uri): ByteArray? {
        return runCatching {
            contentResolver.openInputStream(uri)?.use { stream ->
                val maxBytes = 32 * 1024 * 1024
                val buffer = ByteArray(8192)
                val output = java.io.ByteArrayOutputStream()
                var total = 0

                while (true) {
                    val count = stream.read(buffer)
                    if (count < 0) break
                    total += count
                    require(total <= maxBytes)
                    output.write(buffer, 0, count)
                }
                output.toByteArray()
            } ?: error("openInputStream failed")
        }.getOrElse {
            Toast.makeText(
                this,
                "파일이 너무 크거나 읽을 수 없습니다.",
                Toast.LENGTH_SHORT
            ).show()
            null
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun DataManagementScreen(
    onBack: () -> Unit,
    backupBusy: Boolean,
    onCreateBackup: (Boolean, String) -> Unit,
    onChooseRestoreFile: (((ByteArray) -> Unit) -> Unit),
    onRestoreValidated: (ValidatedBackup) -> Boolean
) {
    val context = androidx.compose.ui.platform.LocalContext.current

    var encrypt by remember { mutableStateOf(false) }
    var passwordDialog by remember { mutableStateOf(false) }

    var restoreBytes by remember { mutableStateOf<ByteArray?>(null) }
    var restoreInspection by remember {
        mutableStateOf<ContainerInspection?>(null)
    }
    var restoreBackup by remember {
        mutableStateOf<ValidatedBackup?>(null)
    }
    var restorePasswordDialog by remember {
        mutableStateOf(false)
    }
    var restoreConfirm by remember {
        mutableStateOf(false)
    }

    val scope = rememberCoroutineScope()
    var validating by remember { mutableStateOf(false) }

    fun validateRestore(bytes: ByteArray, password: String?) {
        if (validating) return
        validating = true
        scope.launch {
            try {
                val chars = password?.toCharArray()
                val result = withContext(Dispatchers.Default) {
                    try { ArmyristPortableDataManager.validateBackup(bytes, chars) }
                    finally { chars?.fill('\u0000') }
                }
                when (result) {
                    is PortableResult.Success -> {
                        restorePasswordDialog = false
                        restoreBackup = result.value
                        restoreConfirm = true
                    }
                    is PortableResult.Error -> Toast.makeText(context, result.message, Toast.LENGTH_LONG).show()
                }
            } finally { validating = false }
        }
    }

    if (validating || backupBusy) PortableWorkDialog()

    BackHandler(onBack = onBack)

    Scaffold(
        topBar = {
            ArmyristTopBar(
                title = "데이터 관리",
                subtitle = "DATA · BACKUP / RESTORE · OFFLINE",
                leadingLabel = "홈",
                leadingIcon = ArmyristTopBarLeadingIcon.HOME,
                onLeading = onBack
            )
        }
    ) { padding ->
        Column(
            Modifier
                .fillMaxSize()
                .padding(padding)
                .verticalScroll(rememberScrollState())
                .padding(16.dp),
            verticalArrangement = Arrangement.spacedBy(14.dp)
        ) {
            val summary = remember {
                ArmyristPortableDataManager.currentSummary(
                    context
                )
            }

            ArmyristPanel(
                modifier = Modifier.fillMaxWidth()
            ) {
                Text(
                    "전체 백업",
                    style = MaterialTheme.typography.titleLarge,
                    fontWeight = FontWeight.Bold
                )
                Spacer(Modifier.height(8.dp))
                Text("현재 낄롬리스 데이터를 하나의 파일로 보관합니다.")
                Spacer(Modifier.height(12.dp))
                DataCount("실셈", summary.countingSheets)
                DataCount("체크리스트", summary.checklists)
                DataCount("시간계획", summary.timePlans)
                DataCount("보고 양식", summary.reportTemplates)
                DataCountText("내 정보", "포함")

                Spacer(Modifier.height(12.dp))
                Row(
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Switch(
                        checked = encrypt,
                        onCheckedChange = { encrypt = it }
                    )
                    Spacer(Modifier.width(8.dp))
                    Column {
                        Text(
                            "파일 암호화",
                            fontWeight = FontWeight.SemiBold
                        )
                        Text(
                            if (encrypt) {
                                "AES-256-GCM으로 보호"
                            } else {
                                "암호화 안 함"
                            },
                            style = MaterialTheme.typography.bodySmall,
                            color = ArmyristColors.SecondaryText
                        )
                    }
                }

                Spacer(Modifier.height(12.dp))
                ArmyristActionButton(
                    text = "백업 생성",
                    onClick = {
                        if (encrypt) passwordDialog = true
                        else onCreateBackup(false, "")
                    },
                    modifier = Modifier.fillMaxWidth(),
                    primary = true
                )
            }

            ArmyristPanel(
                modifier = Modifier.fillMaxWidth()
            ) {
                Text(
                    "전체 복원",
                    style = MaterialTheme.typography.titleLarge,
                    fontWeight = FontWeight.Bold
                )
                Spacer(Modifier.height(8.dp))
                Text(
                    "백업 파일의 데이터로 현재 낄롬리스 데이터를 교체합니다."
                )
                Spacer(Modifier.height(6.dp))
                Text(
                    "복원 실패 시 기존 데이터는 유지됩니다.",
                    style = MaterialTheme.typography.bodySmall,
                    color = ArmyristColors.SecondaryText
                )
                Spacer(Modifier.height(12.dp))
                ArmyristActionButton(
                    text = "백업 파일 선택",
                    onClick = {
                        onChooseRestoreFile { bytes ->
                            restoreBytes = bytes
                            when (
                                val inspection =
                                    ArmyristPortableDataManager
                                        .inspect(bytes)
                            ) {
                                is PortableResult.Success -> {
                                    restoreInspection =
                                        inspection.value
                                    if (inspection.value.encrypted) {
                                        restorePasswordDialog = true
                                    } else {
                                        validateRestore(bytes, null)
                                    }
                                }
                                is PortableResult.Error -> {
                                    Toast.makeText(
                                        context,
                                        inspection.message,
                                        Toast.LENGTH_SHORT
                                    ).show()
                                }
                            }
                        }
                    },
                    modifier = Modifier.fillMaxWidth()
                )
            }

            ArmyristPanel(
                modifier = Modifier.fillMaxWidth()
            ) {
                Text(
                    "개별 데이터 가져오기",
                    style = MaterialTheme.typography.titleLarge,
                    fontWeight = FontWeight.Bold
                )
                Spacer(Modifier.height(8.dp))
                Text("실셈·체크리스트·시간계획·보고 양식 .armyrist 파일을 새 문서로 추가합니다.")
                Spacer(Modifier.height(12.dp))
                ArmyristActionButton(
                    text = "데이터 가져오기",
                    onClick = {
                        context.startActivity(
                            android.content.Intent(
                                context,
                                PortableTransferActivity::class.java
                            ).apply {
                                putExtra(
                                    PortableTransferActivity.EXTRA_MODE,
                                    PortableTransferActivity.MODE_IMPORT
                                )
                            }
                        )
                    },
                    modifier = Modifier.fillMaxWidth()
                )

                Spacer(Modifier.height(8.dp))
                ArmyristActionButton(
                    text = "주변 낄롬리스 수신 (PoC)",
                    onClick = {
                        context.startActivity(
                            android.content.Intent(context, NearbyTransferActivity::class.java)
                        )
                    },
                    modifier = Modifier.fillMaxWidth(),
                    primary = false
                )
            }
        }
    }

    if (passwordDialog) {
        PasswordConfirmDialog(
            title = "백업 파일 암호화",
            onDismiss = { passwordDialog = false },
            onConfirm = { password ->
                passwordDialog = false
                onCreateBackup(true, password)
            }
        )
    }

    if (restorePasswordDialog) {
        PasswordInputDialog(
            title = "암호화된 낄롬리스 파일",
            onDismiss = {
                restorePasswordDialog = false
                restoreBytes = null
            },
            onConfirm = { password ->
                val bytes = restoreBytes ?: return@PasswordInputDialog
                validateRestore(bytes, password)
            }
        )
    }

    if (restoreConfirm) {
        val backup = restoreBackup
        if (backup != null) {
            RestoreConfirmDialog(
                backup = backup,
                current =
                    ArmyristPortableDataManager.currentSummary(
                        context
                    ),
                onDismiss = {
                    restoreConfirm = false
                    restoreBackup = null
                    restoreBytes = null
                },
                onConfirm = {
                    if (onRestoreValidated(backup)) {
                        restoreConfirm = false
                        restoreBackup = null
                        restoreBytes = null
                    }
                }
            )
        }
    }
}

