import com.google.android.gms.nearby.connection.EndpointDiscoveryCallback
import com.google.android.gms.nearby.connection.Payload
import com.google.android.gms.nearby.connection.PayloadCallback
import com.google.android.gms.nearby.connection.PayloadTransferUpdate
import com.google.android.gms.nearby.connection.Strategy
import java.io.File
import java.io.FileNotFoundException

class NearbyConnectionsSenderActivity : ComponentActivity() {
    data class Endpoint(
        val id: String,
        val name: String
    )

    private lateinit var client: ConnectionsClient
    private val endpoints = mutableStateListOf<Endpoint>()
    private var status by mutableStateOf("주변 낄롬리스를 찾는 중입니다.")
    private var connectingEndpoint by mutableStateOf<String?>(null)
    private var activeEndpoint by mutableStateOf<String?>(null)
    private var activePayloadId by mutableStateOf<Long?>(null)

    private val sendFile: File?
        get() = intent.getStringExtra(NearbyConnectionsPoC.EXTRA_SEND_FILE)
            ?.let(::File)

    private val permissionLauncher =
        registerForActivityResult(
            ActivityResultContracts.RequestMultiplePermissions()
        ) { result ->
            if (NearbyPermissionGate.hasRequiredPermissions(this)) {
                startDiscovery()
            } else {
                status = "주변 기기를 찾으려면 근처 기기 접근 권한이 필요합니다."
            }
        }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        client = Nearby.getConnectionsClient(this)
        render()

        if (NearbyPermissionGate.hasRequiredPermissions(this)) {
            startDiscovery()
        } else {
            permissionLauncher.launch(
                NearbyPermissionGate.missingPermissions(this)
            )
        }
    }

    private fun render() = setContent {
        ArmyristTheme {
            Scaffold(
                topBar = {
                    ArmyristTopBar(
                        title = "주변 낄롬리스",
                        subtitle = "Background Receive PoC",
                        leadingLabel = "뒤로",
                        onLeading = { finish() }
                    )
                }
            ) { padding ->
                Column(
                    Modifier
                        .fillMaxSize()
                        .padding(padding)
                        .padding(16.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    ArmyristPanel(Modifier.fillMaxWidth()) {
                        Text(
                            "수신 모드를 켜 둔 주변 낄롬리스를 찾습니다.",
                            fontWeight = FontWeight.Bold
                        )
                        Spacer(Modifier.height(6.dp))
                        Text(status)
                    }

                    OutlinedButton(
                        onClick = { startDiscovery() },
                        modifier = Modifier.fillMaxWidth(),
                        shape = ArmyristPanelShape
                    ) {
                        Text("다시 검색")
                    }

                    if (endpoints.isEmpty()) {
                        Text("아직 발견된 기기가 없습니다.")
                    }

                    endpoints.forEach { endpoint ->
                        ArmyristPanel(Modifier.fillMaxWidth()) {
                            Row(
                                Modifier.fillMaxWidth(),
                                horizontalArrangement =
                                    Arrangement.SpaceBetween
                            ) {
                                Column(Modifier.weight(1f)) {
                                    Text(
                                        endpoint.name,
                                        fontWeight = FontWeight.SemiBold
                                    )
                                    Text(
                                        "Armyrist",
                                        style = MaterialTheme.typography.bodySmall
                                    )
                                }

                                Button(
                                    onClick = { connect(endpoint) },
                                    enabled =
                                        connectingEndpoint == null &&
                                            activeEndpoint == null,
                                    shape = ArmyristPanelShape
                                ) {
                                    Text("보내기")
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    private fun startDiscovery() {
        if (!NearbyPermissionGate.hasRequiredPermissions(this)) {
            permissionLauncher.launch(
                NearbyPermissionGate.missingPermissions(this)
            )
            return
        }

        endpoints.clear()
        status = "주변 낄롬리스를 찾는 중입니다."

        client.stopDiscovery()
        client.startDiscovery(
            NearbyConnectionsPoC.SERVICE_ID,
            endpointDiscoveryCallback,
            DiscoveryOptions.Builder()
                .setStrategy(Strategy.P2P_POINT_TO_POINT)
                .build()
        ).addOnSuccessListener {
            Log.i(
                "ArmyristNearby",
                "startDiscovery SUCCESS serviceId=${NearbyConnectionsPoC.SERVICE_ID} strategy=${NearbyConnectionsPoC.STRATEGY_LABEL}"
            )
            status = "검색 중 · 수신 모드가 켜진 기기를 찾습니다."
        }.addOnFailureListener { error ->
            val diagnostic =
                NearbyConnectionsPoC.diagnosticFailure("startDiscovery", error)
            Log.e(
                "ArmyristNearby",
                "$diagnostic · serviceId=${NearbyConnectionsPoC.SERVICE_ID} strategy=${NearbyConnectionsPoC.STRATEGY_LABEL}",
                error
            )
            status = "주변 기기 검색을 시작하지 못했습니다. 다시 시도해주세요."
        }
    }

    private val endpointDiscoveryCallback =
        object : EndpointDiscoveryCallback() {
            override fun onEndpointFound(
                endpointId: String,
                info: DiscoveredEndpointInfo
            ) {
                if (
                    endpoints.none { it.id == endpointId }
                ) {
                    endpoints += Endpoint(
                        id = endpointId,
                        name =
                            info.endpointName
                                .removePrefix("Armyrist · ")
                                .ifBlank { "Android 기기" }
                    )
                    status = "주변 낄롬리스 ${endpoints.size}대 발견"
                }
            }

            override fun onEndpointLost(endpointId: String) {
                endpoints.removeAll { it.id == endpointId }
            }
        }

    private fun connect(endpoint: Endpoint) {
        val file = sendFile
        if (file == null || !file.isFile) {
            status = "전송할 Portable Data를 찾을 수 없습니다."
            return
        }

        val title =
            intent.getStringExtra(NearbyConnectionsPoC.EXTRA_TITLE)
                ?: "낄롬리스 데이터"
        val type =
            intent.getStringExtra(NearbyConnectionsPoC.EXTRA_TYPE)
                ?: "PORTABLE"

        connectingEndpoint = endpoint.id
        status = "${endpoint.name}에 전송 요청을 보내는 중입니다."

        val localEndpointName =
            NearbyConnectionsPoC.encodeRequestMetadata(
                device = Build.MODEL,
                title = title,
                type = type
            )

        client.requestConnection(
            localEndpointName,
            endpoint.id,
            lifecycleCallback
        ).addOnFailureListener {
            connectingEndpoint = null
            status = "전송 요청을 보낼 수 없습니다."
        }
    }

    private val lifecycleCallback =
        object : ConnectionLifecycleCallback() {
            override fun onConnectionInitiated(
                endpointId: String,
                info: ConnectionInfo
            ) {
                status =
                    if (info.authenticationDigits.isNullOrBlank()) {
                        "상대방의 수신 승인을 기다리는 중입니다."
                    } else {
                        "상대방의 수신 승인을 기다리는 중 · " +
                            "확인 코드 ${info.authenticationDigits}"
                    }

                client.acceptConnection(
                    endpointId,
                    payloadCallback
                )
            }

            override fun onConnectionResult(
                endpointId: String,
                resolution: ConnectionResolution
            ) {
                connectingEndpoint = null

                if (
                    resolution.status.statusCode ==
                    ConnectionsStatusCodes.STATUS_OK
                ) {
                    activeEndpoint = endpointId
                    sendPortable(endpointId)
                } else {
                    activeEndpoint = null
                    status =
                        if (
                            resolution.status.statusCode ==
                            ConnectionsStatusCodes.STATUS_CONNECTION_REJECTED
                        ) {
                            "상대방이 전송을 거절했습니다."
                        } else {
                            "연결하지 못했습니다. 다시 시도해주세요."
                        }
                }
            }

            override fun onDisconnected(endpointId: String) {
                if (activeEndpoint == endpointId) {
                    activeEndpoint = null
                }
            }
        }

    private val payloadCallback =
        object : PayloadCallback() {
            override fun onPayloadReceived(
                endpointId: String,
                payload: Payload
            ) {
                // Sender does not expect incoming payloads in this 1→1 PoC.
                payload.close()
            }

            override fun onPayloadTransferUpdate(
                endpointId: String,
                update: PayloadTransferUpdate
            ) {
                if (activePayloadId != update.payloadId) return

                when (update.status) {
                    PayloadTransferUpdate.Status.IN_PROGRESS -> {
                        if (update.totalBytes > 0) {
                            val percent =
                                (
                                    update.bytesTransferred * 100L /
                                        update.totalBytes
                                ).coerceIn(0, 100)
                            status = "데이터를 보내는 중… ${percent}%"
                        }
                    }

                    PayloadTransferUpdate.Status.SUCCESS -> {
                        status = "전송했습니다."
                        activePayloadId = null
                        activeEndpoint = null
                        client.disconnectFromEndpoint(endpointId)
                    }

                    PayloadTransferUpdate.Status.FAILURE,
                    PayloadTransferUpdate.Status.CANCELED -> {
                        status = "전송하지 못했습니다. 다시 시도해주세요."
                        activePayloadId = null
                        activeEndpoint = null
                        client.disconnectFromEndpoint(endpointId)
                    }
                }
            }
        }

    private fun sendPortable(endpointId: String) {
        val file = sendFile ?: return

        runCatching {
            Payload.fromFile(file).also {
                it.setSensitive(true)
            }
        }.onSuccess { payload ->
            activePayloadId = payload.id
            status = "데이터를 보내는 중…"
            client.sendPayload(endpointId, payload)
                .addOnFailureListener {
                    activePayloadId = null
                    activeEndpoint = null
                    status = "전송을 시작하지 못했습니다."
                }
        }.onFailure {
            activeEndpoint = null
            status =
                if (it is FileNotFoundException) {
                    "전송할 데이터 파일을 찾을 수 없습니다."
                } else {
                    "전송 데이터를 준비할 수 없습니다."
                }
        }
    }

    override fun onDestroy() {
        runCatching { client.stopDiscovery() }
        activeEndpoint?.let {
            runCatching { client.disconnectFromEndpoint(it) }
        }
        super.onDestroy()
    }
}

package com.seolhwa.armyrist

import android.content.Context
import android.net.nsd.NsdManager
import android.net.nsd.NsdServiceInfo
import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import java.io.DataInputStream
import java.io.DataOutputStream
import java.io.File
import java.net.InetAddress
import java.net.ServerSocket
import java.net.Socket
import java.util.UUID
import java.util.concurrent.Executors

/**
 * Minor Patch B Nearby Direct Transfer PoC.
 *
 * Transport: Android NSD (DNS-SD) discovery + a local TCP socket on the same
 * Wi-Fi/LAN. No Armyrist server/account/cloud is involved. Internet access is
 * not required, but both devices must currently share a local IP network.
 * Portable bytes are reused unchanged and are only handed to the existing
 * validation/preview/import flow after the receiver explicitly accepts them.
 */
class NearbyTransferActivity : ComponentActivity() {
    companion object {
        const val EXTRA_SEND_FILE = "sendFile"
        private const val SERVICE_TYPE = "_armyrist._tcp."
        private const val MAX_BYTES = 32 * 1024 * 1024
    }

    data class Peer(val name: String, val host: InetAddress, val port: Int)

    private val io = Executors.newCachedThreadPool()
    private lateinit var nsd: NsdManager
    private var server: ServerSocket? = null
    private var registration: NsdManager.RegistrationListener? = null
    private var discovery: NsdManager.DiscoveryListener? = null

    private val peers = mutableStateListOf<Peer>()
    private var status by mutableStateOf("주변 낄롬리스를 찾는 중입니다.")
    private var incoming by mutableStateOf<ByteArray?>(null)
    private var incomingFrom by mutableStateOf("")

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        nsd = getSystemService(Context.NSD_SERVICE) as NsdManager
        startReceiver()
        startDiscovery()
        render()
    }

    private fun render() = setContent {
        ArmyristTheme {
            val sendFile = remember { intent.getStringExtra(EXTRA_SEND_FILE)?.let(::File) }
            Scaffold(topBar = {
                ArmyristTopBar(
                    title = "주변 낄롬리스",
                    subtitle = "근거리 직접전송 · PoC",
                    leadingLabel = "뒤로",
                    onLeading = { finish() }
                )
            }) { padding ->
                Column(
                    Modifier.fillMaxSize().padding(padding).padding(16.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    ArmyristPanel(Modifier.fillMaxWidth()) {
                        Text("같은 Wi-Fi 또는 로컬 네트워크의 낄롬리스를 찾습니다.", fontWeight = FontWeight.Bold)
                        Spacer(Modifier.height(6.dp))
                        Text("인터넷 서버·계정은 사용하지 않습니다. 두 기기 모두 이 화면을 열어두세요.")
                        Spacer(Modifier.height(8.dp))
                        Text(status, style = MaterialTheme.typography.bodySmall)
                    }

                    if (sendFile != null) {
                        Text("주변 기기", fontWeight = FontWeight.Bold)
                        if (peers.isEmpty()) Text("아직 발견된 기기가 없습니다.")
                        peers.forEach { peer ->
                            ArmyristPanel(Modifier.fillMaxWidth()) {
                                Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                                    Column(Modifier.weight(1f)) {
                                        Text(peer.name, fontWeight = FontWeight.SemiBold)
                                        Text("${peer.host.hostAddress}:${peer.port}", style = MaterialTheme.typography.bodySmall)
                                    }
                                    Button(onClick = {
                                        val bytes = runCatching { sendFile.readBytes() }.getOrNull()
                                        if (bytes != null) send(peer, bytes)
                                    }, shape = ArmyristPanelShape) { Text("보내기") }
                                }
                            }
                        }
                    } else {
                        Text("수신 대기 중", fontWeight = FontWeight.Bold)
                        Text("송신 기기에서 이 기기를 선택하면 수신 요청이 표시됩니다.")
                    }
                }
            }

            incoming?.let { bytes ->
                AlertDialog(
                    onDismissRequest = { incoming = null },
                    title = { Text("낄롬리스 데이터 수신") },
                    text = { Text("${incomingFrom.ifBlank { "주변 기기" }}에서 ${bytes.size} bytes의 데이터를 받았습니다. 내용을 확인하시겠습니까?") },
                    dismissButton = { TextButton(onClick = { incoming = null }) { Text("거절") } },
                    confirmButton = { Button(onClick = {
                        val file = File(cacheDir, "nearby-received-${System.currentTimeMillis()}.armyrist")
                        file.writeBytes(bytes)
                        incoming = null
                        startActivity(android.content.Intent(this@NearbyTransferActivity, PortableTransferActivity::class.java).apply {
                            putExtra(PortableTransferActivity.EXTRA_MODE, PortableTransferActivity.MODE_IMPORT_BYTES)
                            putExtra(PortableTransferActivity.EXTRA_CACHE_FILE, file.absolutePath)
                        })
                    }) { Text("받기") } }
                )
            }
        }
    }

    private fun startReceiver() {
        io.execute {
            runCatching {
                val socket = ServerSocket(0).also { server = it }
                registerService(socket.localPort)
                while (!socket.isClosed) {
                    val client = socket.accept()
                    io.execute { receive(client) }
                }
            }.onFailure { runOnUiThread { status = "수신 대기를 시작할 수 없습니다: ${it.javaClass.simpleName}" } }
        }
    }

    private fun receive(socket: Socket) {
        socket.use { s ->
            runCatching {
                val input = DataInputStream(s.getInputStream())
                val magic = input.readUTF()
                require(magic == "ARMYRIST_NEARBY_V1")
                val length = input.readInt()
                require(length in 1..MAX_BYTES)
                val bytes = ByteArray(length)
                input.readFully(bytes)
                runOnUiThread {
                    incomingFrom = s.inetAddress.hostAddress ?: "주변 기기"
                    incoming = bytes
                    status = "수신 요청이 도착했습니다."
                }
            }.onFailure { runOnUiThread { status = "수신 데이터가 올바르지 않습니다." } }
        }
    }

    private fun registerService(port: Int) {
        val info = NsdServiceInfo().apply {
            serviceName = "Armyrist-${android.os.Build.MODEL}-${UUID.randomUUID().toString().take(4)}"
            serviceType = SERVICE_TYPE
            setPort(port)
        }
        val listener = object : NsdManager.RegistrationListener {
            override fun onServiceRegistered(serviceInfo: NsdServiceInfo) { runOnUiThread { status = "수신 대기 중 · 주변 기기를 검색하고 있습니다." } }
            override fun onRegistrationFailed(serviceInfo: NsdServiceInfo, errorCode: Int) { runOnUiThread { status = "주변 전송 등록 실패 ($errorCode)" } }
            override fun onServiceUnregistered(serviceInfo: NsdServiceInfo) = Unit
            override fun onUnregistrationFailed(serviceInfo: NsdServiceInfo, errorCode: Int) = Unit
        }
        registration = listener
        nsd.registerService(info, NsdManager.PROTOCOL_DNS_SD, listener)
    }

    private fun startDiscovery() {
        val listener = object : NsdManager.DiscoveryListener {
            override fun onDiscoveryStarted(serviceType: String) = Unit
            override fun onServiceFound(serviceInfo: NsdServiceInfo) {
                if (serviceInfo.serviceType != SERVICE_TYPE) return
                nsd.resolveService(serviceInfo, object : NsdManager.ResolveListener {
                    override fun onResolveFailed(serviceInfo: NsdServiceInfo, errorCode: Int) = Unit
                    @Suppress("DEPRECATION")
                    override fun onServiceResolved(resolved: NsdServiceInfo) {
                        val host = resolved.host ?: return
                        val peer = Peer(resolved.serviceName, host, resolved.port)
                        runOnUiThread {
                            if (peers.none { it.host == peer.host && it.port == peer.port }) peers.add(peer)
                        }
                    }
                })
            }
            override fun onServiceLost(serviceInfo: NsdServiceInfo) { runOnUiThread { peers.removeAll { it.name == serviceInfo.serviceName } } }
            override fun onDiscoveryStopped(serviceType: String) = Unit
            override fun onStartDiscoveryFailed(serviceType: String, errorCode: Int) { runOnUiThread { status = "주변 검색 시작 실패 ($errorCode)" } }
            override fun onStopDiscoveryFailed(serviceType: String, errorCode: Int) = Unit
        }
        discovery = listener
        nsd.discoverServices(SERVICE_TYPE, NsdManager.PROTOCOL_DNS_SD, listener)
    }

    private fun send(peer: Peer, bytes: ByteArray) {
        status = "${peer.name}에 전송 중..."
        io.execute {
            runCatching {
                require(bytes.size <= MAX_BYTES)
                Socket(peer.host, peer.port).use { socket ->
                    val out = DataOutputStream(socket.getOutputStream())
                    out.writeUTF("ARMYRIST_NEARBY_V1")
                    out.writeInt(bytes.size)
                    out.write(bytes)
                    out.flush()
                }
            }.onSuccess { runOnUiThread { status = "전송 완료 · 수신 기기에서 확인하세요." } }
                .onFailure { runOnUiThread { status = "전송 실패: ${it.javaClass.simpleName}" } }
        }
    }

    override fun onDestroy() {
        discovery?.let { runCatching { nsd.stopServiceDiscovery(it) } }
        registration?.let { runCatching { nsd.unregisterService(it) } }
        runCatching { server?.close() }
        io.shutdownNow()
        super.onDestroy()
    }
}

package com.seolhwa.armyrist

import android.content.Intent
import android.os.Bundle
import android.widget.Toast
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.result.contract.ActivityResultContracts
import androidx.core.content.FileProvider
import java.io.File
import java.time.Instant
import java.time.LocalDate
import java.time.ZoneOffset
import java.time.format.DateTimeFormatter
import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.text.input.PasswordVisualTransformation
import androidx.compose.ui.unit.dp
