                )
            },
            text = {
                Text(
                    "'$title'은 날짜 기능 이전 형식입니다. 휴지통으로 이동한 뒤에도 이전 형식 그대로 복구할 수 있습니다.",
                    style = MaterialTheme.typography.bodyMedium
