            TimelineList(
                plan = plan,
                conflicts = conflicts,
                selectionMode = selectionMode,
                selectedKeys = selectedKeys,
                onToggleNode = { toggleSelection(nodeSelectionKey(it)) },
                onToggleLink = { from, to -> toggleSelection(linkSelectionKey(from, to)) },
