@Composable
fun AutoUpdateCheckHost(
    onUpdateAvailabilityChanged: (UpdateReleaseMetadata?) -> Unit = {}
) {
    val context = LocalContext.current
    val manager = remember { ArmyristUpdateManager(context) }
    var available by remember { mutableStateOf<UpdateReleaseMetadata?>(null) }

    LaunchedEffect(Unit) {
        if (UpdateSessionState.automaticCheckAttempted) return@LaunchedEffect
        UpdateSessionState.automaticCheckAttempted = true

        val prefs = manager.preferences()
        if (!prefs.isAutomaticCheckDue()) return@LaunchedEffect

        when (val result = manager.check(manual = false)) {
            is UpdateCheckResult.Available -> {
                onUpdateAvailabilityChanged(result.release)
                if (UpdateSessionState.shouldPrompt(result.release.versionCode)) {
                    available = result.release
                }
            }
            is UpdateCheckResult.Latest,
            is UpdateCheckResult.NoNewerEligibleRelease -> {
                onUpdateAvailabilityChanged(null)
            }
            is UpdateCheckResult.Failure -> Unit // Automatic checks never interrupt core use.
        }
    }

    available?.let { release ->
        AlertDialog(
            onDismissRequest = { available = null },
            shape = ArmyristPanelShape,
            containerColor = ArmyristColors.RaisedSurface,
            tonalElevation = 0.dp,
            titleContentColor = ArmyristColors.PrimaryText,
            textContentColor = ArmyristColors.PrimaryText,
            title = {
                Column {
                    Text(
                        "새로운 낄롬리스 ${release.versionName}",
                        style = MaterialTheme.typography.headlineSmall,
                        fontWeight = FontWeight.Bold
                    )
                    Spacer(Modifier.height(3.dp))
                    Text(
                        "업데이트를 사용할 수 있습니다.",
                        style = MaterialTheme.typography.bodyMedium,
                        color = ArmyristColors.SecondaryText
                    )
                }
            },
            text = {
                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    HorizontalDivider(color = ArmyristColors.SoftBorder)
                    Text(
                        "주요 변경사항",
                        fontWeight = FontWeight.Bold,
                        color = ArmyristColors.SecondaryText
                    )
                    if (release.releaseNotes.isEmpty()) {
                        Text(
                            "변경사항이 제공되지 않았습니다.",
                            color = ArmyristColors.SecondaryText
                        )
                    } else {
                        release.releaseNotes.take(4).forEach {
                            Text(
                                "• $it",
                                style = MaterialTheme.typography.bodyMedium,
                                color = ArmyristColors.SecondaryText
                            )
                        }
                    }
                }
            },
            dismissButton = {
                OutlinedButton(
                    onClick = { available = null },
                    shape = ArmyristPanelShape,
                    border = BorderStroke(1.dp, ArmyristColors.SoftBorder),
                    colors = ButtonDefaults.outlinedButtonColors(
                        containerColor = ArmyristColors.RaisedSurface,
                        contentColor = ArmyristColors.PrimaryText
                    )
                ) {
                    Text("나중에")
                }
            },
            confirmButton = {
                Button(
                    onClick = {
                        available = null
                        context.startActivity(
                            Intent(context, UserProfileActivity::class.java)
                                .putExtra(UserProfileActivity.EXTRA_START_UPDATE, true)
                        )
                    },
                    shape = ArmyristPanelShape,
                    colors = ButtonDefaults.buttonColors(
                        containerColor = ArmyristColors.PrimaryControl,
                        contentColor = ArmyristColors.OnDark
                    )
                ) {
                    Text("업데이트", fontWeight = FontWeight.Bold)
                }
            }
        )
    }
}

@Composable
fun UpdateAppInfoPanel(startUpdateImmediately: Boolean = false) {
    val context = LocalContext.current
    val manager = remember { ArmyristUpdateManager(context) }
    val scope = rememberCoroutineScope()
    val installed = remember { manager.installedVersion() }

    var interval by remember { mutableStateOf(manager.preferences().interval) }
    var menuExpanded by remember { mutableStateOf(false) }
    var checking by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    var available by remember {
        mutableStateOf(UpdateSessionState.latestAvailable ?: manager.knownAvailable())
    }
    var downloadState by remember { mutableStateOf<DownloadUiState>(DownloadUiState.Idle) }
    var latestConfirmed by remember { mutableStateOf(false) }
    var downloadJob by remember { mutableStateOf<Job?>(null) }

    fun beginDownload(release: UpdateReleaseMetadata) {
        if (downloadJob?.isActive == true) return
        downloadState = DownloadUiState.Preparing
        downloadJob = scope.launch {
            val result = manager.downloadAndValidate(
                release = release,
                onProgress = { progress ->
                    downloadState = DownloadUiState.Downloading(progress)
                },
                onValidating = {
                    downloadState = DownloadUiState.Validating
                }
            )
            result.onSuccess { file ->
                downloadState = DownloadUiState.Ready(file.absolutePath)
                when (UpdateInstaller.launch(context, file)) {
                    InstallLaunchResult.Launched -> {
                        message = "Android 설치 화면을 열었습니다. 설치 여부는 시스템 화면에서 선택해주세요."
                    }
                    InstallLaunchResult.PermissionRequired -> {
                        message = "이 출처의 앱 설치 권한을 허용한 뒤 업데이트를 다시 눌러주세요."
                    }
                }
            }.onFailure { error ->
                if (error is kotlinx.coroutines.CancellationException) {
                    downloadState = DownloadUiState.Idle
                    message = "업데이트 다운로드를 취소했습니다."
                } else {
                    downloadState = DownloadUiState.Failed(
                        error.message ?: "업데이트 파일을 다운로드하거나 검증하지 못했습니다."
                    )
                }
            }
        }
    }

    LaunchedEffect(startUpdateImmediately) {
        if (!startUpdateImmediately) return@LaunchedEffect
        val release = available
        if (release != null) {
            beginDownload(release)
        } else {
            checking = true
            when (val result = manager.check(manual = true)) {
                is UpdateCheckResult.Available -> {
                    available = result.release
                    beginDownload(result.release)
                }
                is UpdateCheckResult.Latest -> {
                    latestConfirmed = true
                    message = "현재 최신 버전입니다."
                }
                is UpdateCheckResult.NoNewerEligibleRelease -> {
                    latestConfirmed = true
                    message = "사용 가능한 새로운 Stable 업데이트가 없습니다."
                }
                is UpdateCheckResult.Failure -> message = result.message
            }
            checking = false
        }
    }

    ArmyristPanel(Modifier.fillMaxWidth()) {
        Text("앱 정보", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold)
        Spacer(Modifier.height(10.dp))

        InfoRow("현재 버전", installed.displayName)
        Spacer(Modifier.height(6.dp))
        InfoRow(
            "업데이트 상태",
            when {
                available != null -> "새 버전 ${available!!.versionName} 사용 가능"
                checking -> "확인 중"
                latestConfirmed -> "최신 버전 사용 중"
                else -> "업데이트 확인 필요"
            }
        )

        available?.let { release ->
            Spacer(Modifier.height(12.dp))
            HorizontalDivider(color = ArmyristColors.Border)
            Spacer(Modifier.height(10.dp))
            Text("주요 변경사항", fontWeight = FontWeight.Bold)
            Spacer(Modifier.height(6.dp))
            if (release.releaseNotes.isEmpty()) {
                Text("변경사항이 제공되지 않았습니다.", color = ArmyristColors.SecondaryText)
            } else {
                release.releaseNotes.forEach { note ->
                    Text("• $note", style = MaterialTheme.typography.bodyMedium)
                }
            }
        }

        Spacer(Modifier.height(14.dp))
        Button(
            enabled = !checking && downloadJob?.isActive != true,
            onClick = {
                checking = true
                message = null
                scope.launch {
                    when (val result = manager.check(manual = true)) {
                        is UpdateCheckResult.Available -> {
                            available = result.release
                            latestConfirmed = false
                            message = "새로운 낄롬리스 ${result.release.versionName} 버전이 있습니다."
                        }
                        is UpdateCheckResult.Latest -> {
                            available = null
                            latestConfirmed = true
                            message = "현재 최신 버전입니다."
                        }
                        is UpdateCheckResult.NoNewerEligibleRelease -> {
                            available = null
                            latestConfirmed = true
                            message = "사용 가능한 새로운 Stable 업데이트가 없습니다."
                        }
                        is UpdateCheckResult.Failure -> message = result.message
                    }
                    checking = false
                }
            },
            modifier = Modifier.fillMaxWidth().heightIn(min = 48.dp),
            shape = ArmyristPanelShape,
            colors = ButtonDefaults.buttonColors(
                containerColor = ArmyristColors.PrimaryControl,
                contentColor = ArmyristColors.OnDark
            )
        ) {
            if (checking) {
                CircularProgressIndicator(
                    modifier = Modifier.size(18.dp),
                    strokeWidth = 2.dp,
                    color = ArmyristColors.OnDark
                )
                Spacer(Modifier.width(8.dp))
                Text("확인 중")
            } else {
                Text("업데이트 확인", fontWeight = FontWeight.Bold)
            }
        }

        available?.let { release ->
            Spacer(Modifier.height(8.dp))
            OutlinedButton(
                enabled = downloadJob?.isActive != true,
                onClick = { beginDownload(release) },
                modifier = Modifier.fillMaxWidth().heightIn(min = 48.dp),
                shape = ArmyristPanelShape,
                border = BorderStroke(1.dp, ArmyristColors.PrimaryControl)
            ) {
                Text("낄롬리스 ${release.versionName} 업데이트")
            }
        }

        Spacer(Modifier.height(14.dp))
        Text("자동 업데이트 확인", style = MaterialTheme.typography.labelLarge, fontWeight = FontWeight.Bold)
        Spacer(Modifier.height(6.dp))
        Box(Modifier.fillMaxWidth()) {
            OutlinedButton(
                onClick = { menuExpanded = true },
                modifier = Modifier.fillMaxWidth(),
                shape = ArmyristPanelShape
            ) {
                Text(interval.displayName, modifier = Modifier.weight(1f))
                Text("▼")
            }
            DropdownMenu(
                expanded = menuExpanded,
                onDismissRequest = { menuExpanded = false }
            ) {
                UpdateCheckInterval.entries.forEach { option ->
                    DropdownMenuItem(
                        text = { Text(option.displayName) },
                        onClick = {
                            interval = option
                            manager.preferences().interval = option
                            menuExpanded = false
                        }
                    )
                }
            }
        }
        Text(
            "자동 확인은 앱을 사용할 때 주기가 지난 경우에만 실행되며, 자동 다운로드나 자동 설치는 하지 않습니다.",
            style = MaterialTheme.typography.bodySmall,
            color = ArmyristColors.SecondaryText
        )

        when (val state = downloadState) {
            DownloadUiState.Idle -> Unit
            DownloadUiState.Preparing -> {
                Spacer(Modifier.height(14.dp))
                Text("다운로드 준비", fontWeight = FontWeight.Bold)
                LinearProgressIndicator(modifier = Modifier.fillMaxWidth())
            }
            is DownloadUiState.Downloading -> {
                Spacer(Modifier.height(14.dp))
                Text(
                    state.progress?.let { "다운로드 중 · $it%" } ?: "다운로드 중",
                    fontWeight = FontWeight.Bold
                )
                Spacer(Modifier.height(6.dp))
                if (state.progress != null) {
                    LinearProgressIndicator(
                        progress = { state.progress / 100f },
                        modifier = Modifier.fillMaxWidth()
                    )
                } else {
                    LinearProgressIndicator(modifier = Modifier.fillMaxWidth())
                }
                Spacer(Modifier.height(6.dp))
                Text("다운로드 완료 후 APK와 서명을 검증합니다.", style = MaterialTheme.typography.bodySmall)
                TextButton(onClick = {
                    downloadJob?.cancel()
                    downloadState = DownloadUiState.Idle
                    message = "업데이트 다운로드를 취소했습니다."
                }) { Text("다운로드 취소") }
            }
            DownloadUiState.Validating -> {
                Spacer(Modifier.height(14.dp))
                Text("검증 중", fontWeight = FontWeight.Bold)
                Spacer(Modifier.height(6.dp))
                LinearProgressIndicator(modifier = Modifier.fillMaxWidth())
                Text(
                    "APK, Package, Version, SHA-256, Signing Identity를 확인합니다.",
                    style = MaterialTheme.typography.bodySmall
                )
            }
            is DownloadUiState.Ready -> {
                Spacer(Modifier.height(12.dp))
                Text("검증 완료 · 설치 준비 완료", fontWeight = FontWeight.Bold)
            }
            is DownloadUiState.Failed -> {
                Spacer(Modifier.height(12.dp))
                Text("다운로드 실패", color = MaterialTheme.colorScheme.error, fontWeight = FontWeight.Bold)
                Text(state.message, style = MaterialTheme.typography.bodySmall)
            }
        }

        message?.let {
            Spacer(Modifier.height(10.dp))
            Text(it, style = MaterialTheme.typography.bodySmall, color = ArmyristColors.SecondaryText)
        }
    }
}

@Composable
private fun InfoRow(label: String, value: String) {
    Row(Modifier.fillMaxWidth(), verticalAlignment = Alignment.CenterVertically) {
        Text(label, modifier = Modifier.weight(1f), color = ArmyristColors.SecondaryText)
        Text(value, fontWeight = FontWeight.SemiBold)
    }
}

private sealed interface DownloadUiState {
    data object Idle : DownloadUiState
    data object Preparing : DownloadUiState
    data class Downloading(val progress: Int?) : DownloadUiState
    data object Validating : DownloadUiState
    data class Ready(val path: String) : DownloadUiState
    data class Failed(val message: String) : DownloadUiState
}

package com.seolhwa.armyrist.home

import com.seolhwa.armyrist.timeplan.v3.domain.*
import java.time.LocalDateTime
import org.junit.Assert.*
import org.junit.Test

class HomeBannerTest {
    private val now = LocalDateTime.of(2026, 10, 20, 12, 0)
    private fun plan(id: String = "p", start: LocalDateTime = now.minusHours(1), end: LocalDateTime = now.plusHours(1)) =
        DateAwareTimePlan(id, "계획 $id", start = DateTimeAnchor(DateTimeValue.explicit(start)),
            end = DateTimeAnchor(DateTimeValue.explicit(end)), createdAt = "0", updatedAt = "0")
    private fun action(id: String, at: LocalDateTime, complete: Boolean = false) =
        TimePlanActionItem(id = id, parentPointId = DateTimePlanRules.START_ID, content = id,
            scheduledDateTime = at, completionState = if (complete) ActionCompletionState.COMPLETE else ActionCompletionState.INCOMPLETE)

    @Test fun startIsInclusiveAndEndExclusive() {
        val p = plan()
        assertTrue(TimePlanLiveStatus.isActive(p, now))
        assertTrue(TimePlanLiveStatus.isActive(p, now.minusHours(1)))
        assertFalse(TimePlanLiveStatus.isActive(p, now.plusHours(1)))
        assertFalse(TimePlanLiveStatus.isActive(p, now.minusHours(1).minusSeconds(1)))
    }
    @Test fun overnightPlanUsesDateNotJustClockTime() {
        val p = plan(start = now.minusDays(1).withHour(23), end = now.withHour(2))
        assertTrue(TimePlanLiveStatus.isActive(p, now.withHour(1)))
        assertFalse(TimePlanLiveStatus.isActive(p, now.plusDays(1).withHour(1)))
    }
    @Test fun relativeAndLegacyTemplatesAreNotLive() {
        assertFalse(TimePlanLiveStatus.isActive(plan().copy(dateDisplayMode = TimePlanDateDisplayMode.RELATIVE_D_DAY), now))
        assertFalse(TimePlanLiveStatus.isActive(plan().copy(legacyDateMigrationRequired = true), now))
    }
    @Test fun missingOrReversedBoundsAreNotLive() {
        assertFalse(TimePlanLiveStatus.isActive(plan().copy(end = DateTimeAnchor()), now))
        assertFalse(TimePlanLiveStatus.isActive(plan().copy(start = DateTimeAnchor()), now))
        assertFalse(TimePlanLiveStatus.isActive(plan(start = now.plusHours(2), end = now), now))
    }
    @Test fun finalRangeCanSupplyMissingEnd() {
        val p = plan().copy(end = DateTimeAnchor(), finalPoint = DateTimeEvent("f", TimeEventKind.FINAL, 0, "최종",
            EventDateTimeSpec.Range(DateTimeValue.explicit(now), DateTimeValue.explicit(now.plusHours(2)))))
        assertTrue(TimePlanLiveStatus.isActive(p, now.plusHours(1)))
    }
    @Test fun allConcurrentPlansAreShownDeterministically() {
        val a = plan("a", end = now.plusMinutes(20)); val b = plan("b", end = now.plusMinutes(10))
        assertEquals(listOf("b", "a"), TimePlanLiveStatus.activePlans(listOf(a, b), now).map { it.id })
    }
    @Test fun nextSkipsCompletedAndPastActionsAcrossPlans() {
        val a = plan("a").copy(actions = listOf(action("past", now.minusMinutes(1)), action("done", now.plusMinutes(1), true), action("later", now.plusMinutes(30))))
        val b = plan("b").copy(actions = listOf(action("next", now.plusMinutes(5))))
        val next = TimePlanLiveStatus.nextAction(listOf(a, b), now)!!
        assertEquals("b", next.plan.id); assertEquals("next", next.action.id)
    }
    @Test fun actionExactlyNowIsEligible() {
        assertEquals("now", TimePlanLiveStatus.nextAction(listOf(plan().copy(actions = listOf(action("now", now)))), now)?.action?.id)
    }
    @Test fun noUpcomingActionReturnsNull() {
        assertNull(TimePlanLiveStatus.nextAction(emptyList(), now))
        assertNull(TimePlanLiveStatus.nextAction(listOf(plan().copy(actions = listOf(action("old", now.minusMinutes(1))))), now))
    }
    @Test fun selectedPlanSetDoesNotLeakOtherActions() {
        val a = plan("a").copy(actions = listOf(action("a", now.plusMinutes(20))))
        val b = plan("b").copy(actions = listOf(action("b", now.plusMinutes(1))))
        assertEquals("a", TimePlanLiveStatus.nextAction(listOf(a, b).filter { it.id == "a" }, now)?.action?.id)
    }
    @Test fun relativeTemplatesDoNotContributeNextActions() {
        val p = plan().copy(dateDisplayMode = TimePlanDateDisplayMode.RELATIVE_D_DAY, actions = listOf(action("template", now.plusMinutes(1))))
        assertNull(TimePlanLiveStatus.nextAction(listOf(p), now))
    }
    @Test fun emptyAndCorruptSettingsUseTimePlanDefaults() {
        assertEquals(HomeBannerConfig(), HomeBannerCodec.decode(null))
        assertEquals(HomeBannerConfig(), HomeBannerCodec.decode("broken"))
        assertEquals(HomeBannerConfig(), HomeBannerCodec.decode("{}"))
    }
    @Test fun savedNoticeAndSelectionRoundTripIncludingUnicode() {
        val c = HomeBannerConfig(HomeBannerMode.NOTICE, "plan-한글", "진행", "다음", "공지 😀", "첫 줄\n둘째 줄")
        assertEquals(c, HomeBannerCodec.decode(HomeBannerCodec.encode(c)))
    }
    @Test fun hiddenBannerStaysHiddenAfterRestart() {
        val c = HomeBannerConfig(mode = HomeBannerMode.HIDDEN)
        assertEquals(HomeBannerMode.HIDDEN, HomeBannerCodec.decode(HomeBannerCodec.encode(c)).mode)
    }
    @Test fun whitespaceHeadingsFallBackAndContentIsBounded() {
        val c = HomeBannerConfig(planId = " ", currentHeading = " ", nextHeading = "", noticeBody = "a".repeat(2000)).normalized()
        assertNull(c.planId); assertEquals("현재 진행중인 시간계획", c.currentHeading)
        assertEquals("다음 실시사항", c.nextHeading); assertEquals(1000, c.noticeBody.length)
    }
    @Test fun unknownModeIsForwardCompatible() {
        assertEquals(HomeBannerMode.TIME_PLAN, HomeBannerCodec.decode("{\"mode\":\"FUTURE\"}").mode)
    }
}
